import{_ as a,o as l,c as r,ag as i}from"./chunks/framework.DGzMGr_a.js";const b=JSON.parse('{"title":"GVG攻城战与领土战争全面攻略","description":"RO3 GVG 100v100攻城战与领土战争玩法详解，含职业搭配、战术策略、装备推荐。","frontmatter":{"title":"GVG攻城战与领土战争全面攻略","description":"RO3 GVG 100v100攻城战与领土战争玩法详解，含职业搭配、战术策略、装备推荐。","lastUpdated":true},"headers":[],"relativePath":"guide/gvg-strategy.md","filePath":"guide/gvg-strategy.md","lastUpdated":1779362930000}'),d={name:"guide/gvg-strategy.md"};function e(o,t,h,n,s,g){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="gvg攻城战与领土战争全面攻略" tabindex="-1">GVG攻城战与领土战争全面攻略 <a class="header-anchor" href="#gvg攻城战与领土战争全面攻略" aria-label="Permalink to &quot;GVG攻城战与领土战争全面攻略&quot;">​</a></h1><p>RO3的GVG（公会战）是游戏的核心PvP玩法，支持最高100v100的同屏激战。根据官方公布的信息，GVG不仅延续了RO经典的攻城战体验，还加入了全新的战略维度。</p><h2 id="gvg基础规则" tabindex="-1">GVG基础规则 <a class="header-anchor" href="#gvg基础规则" aria-label="Permalink to &quot;GVG基础规则&quot;">​</a></h2><h3 id="攻城战-emperium攻城战" tabindex="-1">攻城战（Emperium攻城战） <a class="header-anchor" href="#攻城战-emperium攻城战" aria-label="Permalink to &quot;攻城战（Emperium攻城战）&quot;">​</a></h3><ul><li><strong>规模</strong>：双方各50-100人</li><li><strong>目标</strong>：击破对方公会的「Emperium」核心水晶</li><li><strong>时长</strong>：约45分钟</li><li><strong>地图</strong>：围绕城堡的多层结构，包含城墙、城门、内部庭院、王座厅</li></ul><h3 id="领土战-领地争夺战" tabindex="-1">领土战（领地争夺战） <a class="header-anchor" href="#领土战-领地争夺战" aria-label="Permalink to &quot;领土战（领地争夺战）&quot;">​</a></h3><ul><li><strong>规模</strong>：公会联盟级别的大规模战斗</li><li><strong>地图</strong>：多块独立领土，每块地形不同</li><li><strong>机制</strong>：控制据点获取资源，赛季结算奖励</li><li><strong>外交</strong>：公会之间可结盟、宣战</li></ul><h2 id="职业分工推荐" tabindex="-1">职业分工推荐 <a class="header-anchor" href="#职业分工推荐" aria-label="Permalink to &quot;职业分工推荐&quot;">​</a></h2><h3 id="前排-坦克-肉盾" tabindex="-1">前排（坦克/肉盾） <a class="header-anchor" href="#前排-坦克-肉盾" aria-label="Permalink to &quot;前排（坦克/肉盾）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业</th><th>职责</th><th>关键技能</th></tr></thead><tbody><tr><td>骑士</td><td>主坦克，吸收伤害</td><td>骑乘、自动防御、反击</td></tr><tr><td>十字军</td><td>副坦，团队保护</td><td>牺牲、圣十字审判、盾系技能</td></tr></tbody></table><h3 id="后排-输出" tabindex="-1">后排（输出） <a class="header-anchor" href="#后排-输出" aria-label="Permalink to &quot;后排（输出）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业</th><th>职责</th><th>关键技能</th></tr></thead><tbody><tr><td>巫师</td><td>AOE清场</td><td>暴风雪、陨石术、怒雷强击</td></tr><tr><td>猎人</td><td>远程点杀</td><td>锐利射击、猎鹰突击</td></tr><tr><td>刺客</td><td>切后排、偷水晶</td><td>音速投掷、伪装、心灵震波</td></tr></tbody></table><h3 id="辅助-治疗-增益" tabindex="-1">辅助（治疗/增益） <a class="header-anchor" href="#辅助-治疗-增益" aria-label="Permalink to &quot;辅助（治疗/增益）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业</th><th>职责</th><th>关键技能</th></tr></thead><tbody><tr><td>祭司</td><td>群体治疗、复活</td><td>光耀之堂、复活术、圣母之祈福</td></tr><tr><td>吟游诗人</td><td>团队增益</td><td>布莱奇之诗、战鼓震天</td></tr><tr><td>贤者</td><td>属性防护</td><td>地元素领域、水元素领域</td></tr></tbody></table><h3 id="战术-特殊职能" tabindex="-1">战术（特殊职能） <a class="header-anchor" href="#战术-特殊职能" aria-label="Permalink to &quot;战术（特殊职能）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业</th><th>职责</th><th>关键技能</th></tr></thead><tbody><tr><td>流氓</td><td>骚扰、偷取</td><td>伪装、背刺、强盗之魂</td></tr><tr><td>铁匠</td><td>装备维修、范围控场</td><td>大地之击、速度激发</td></tr></tbody></table><h2 id="攻城战战术策略" tabindex="-1">攻城战战术策略 <a class="header-anchor" href="#攻城战战术策略" aria-label="Permalink to &quot;攻城战战术策略&quot;">​</a></h2><h3 id="进攻方策略" tabindex="-1">进攻方策略 <a class="header-anchor" href="#进攻方策略" aria-label="Permalink to &quot;进攻方策略&quot;">​</a></h3><ol><li><p><strong>破门阶段</strong></p><ul><li>集中火力攻破城门</li><li>骑士/十字军顶在前面吸收箭塔伤害</li><li>巫师在后排AOE压制城墙上的防守方</li></ul></li><li><p><strong>庭院争夺</strong></p><ul><li>占领庭院后建立临时据点</li><li>祭司在后方建立治疗阵地</li><li>分散站位防止AOE团灭</li></ul></li><li><p><strong>王座厅决战</strong></p><ul><li>刺客/流氓绕后偷袭Emp水晶</li><li>正面部队牵制防守方主力</li><li>控制水晶房间入口，分批进攻</li></ul></li></ol><h3 id="防守方策略" tabindex="-1">防守方策略 <a class="header-anchor" href="#防守方策略" aria-label="Permalink to &quot;防守方策略&quot;">​</a></h3><ol><li><p><strong>城门防守</strong></p><ul><li>在城墙上布置远程职业（猎人、巫师）</li><li>城门口设置陷阱（猎人职业）</li><li>保留复活点附近的控制权</li></ul></li><li><p><strong>分层防御</strong></p><ul><li>第一道防线：城门</li><li>第二道防线：庭院入口</li><li>第三道防线：王座厅门口</li><li>最后防线：Emp水晶房间</li></ul></li><li><p><strong>反制战术</strong></p><ul><li>安排刺客巡逻，发现并击杀绕后单位</li><li>贤者布置领域技能封锁关键路口</li><li>祭司保存复活术CD，关键时刻拉起核心成员</li></ul></li></ol><h2 id="装备推荐" tabindex="-1">装备推荐 <a class="header-anchor" href="#装备推荐" aria-label="Permalink to &quot;装备推荐&quot;">​</a></h2><h3 id="pvp装备优先级" tabindex="-1">PvP装备优先级 <a class="header-anchor" href="#pvp装备优先级" aria-label="Permalink to &quot;PvP装备优先级&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业定位</th><th>核心属性</th><th>推荐装备方向</th></tr></thead><tbody><tr><td>坦克</td><td>血量、防御、减伤</td><td>高精炼防具、HP增加卡片</td></tr><tr><td>物理输出</td><td>暴击、穿透、攻速</td><td>高ATK武器、暴击卡片</td></tr><tr><td>魔法输出</td><td>魔攻、穿透、冷却</td><td>高MATK武器、魔穿卡片</td></tr><tr><td>治疗</td><td>治疗量、MP回复</td><td>高INT装备、SP回复卡片</td></tr></tbody></table><h3 id="pvp卡片推荐" tabindex="-1">PvP卡片推荐 <a class="header-anchor" href="#pvp卡片推荐" aria-label="Permalink to &quot;PvP卡片推荐&quot;">​</a></h3><ul><li><strong>武器卡片</strong>：对玩家伤害增加、异常状态触发</li><li><strong>防具卡片</strong>：减少玩家伤害、异常状态抗性</li><li><strong>披风卡片</strong>：闪避、减伤</li><li><strong>鞋子卡片</strong>：移动速度、HP/SP回复</li></ul><h2 id="公会管理建议" tabindex="-1">公会管理建议 <a class="header-anchor" href="#公会管理建议" aria-label="Permalink to &quot;公会管理建议&quot;">​</a></h2><ol><li><strong>人员配置</strong>：建议40%输出、20%坦克、20%治疗、20%战术职业</li><li><strong>指挥系统</strong>：设立总指挥1名、前线指挥2名、后勤管理1名</li><li><strong>赛前准备</strong>：提前30分钟集合，检查装备和药水</li><li><strong>战后复盘</strong>：记录战斗数据，分析胜负原因</li></ol><h2 id="赛季制gvg" tabindex="-1">赛季制GVG <a class="header-anchor" href="#赛季制gvg" aria-label="Permalink to &quot;赛季制GVG&quot;">​</a></h2><p>RO3的GVG将采用赛季制（每赛季3-4个月），每个赛季结束后根据公会排名发放奖励，包括：</p><ul><li>限定称号</li><li>赛季专属装备</li><li>领地资源加成</li><li>公会仓库奖励</li></ul><blockquote><p><strong>提示</strong>：以上攻略基于官方公布的信息和经典RO设定整理，正式上线后可能会有调整。建议关注官方公告获取最新GVG信息。</p></blockquote>',32)])])}const c=a(d,[["render",e]]);export{b as __pageData,c as default};
